cd assets/fonts && node -e '
const fs=require("fs");
const css=fs.readFileSync("fonts.css","utf8");
const blocks=css.split("@font-face").slice(1);
const seen={};
for(const b of blocks){
  const fam=(b.match(/font-family: .([^;]+)./)||[])[1];
  const wt=(b.match(/font-weight: (\d+)/)||[])[1];
  const url=(b.match(/url\((https:[^)]+)\)/)||[])[1];
  if(!fam||!wt||!url) continue;
  if(!b.includes("U+0000-00FF")) continue;
  seen[fam+"-"+wt]=url;
}
const map={"Cinzel-500":"cinzel-500.woff2","Cinzel-600":"cinzel-600.woff2","Cinzel-700":"cinzel-700.woff2","Inter-400":"inter-400.woff2","Inter-500":"inter-500.woff2","Inter-600":"inter-600.woff2","Inter-700":"inter-700.woff2","Inter-800":"inter-800.woff2"};
for(const [k,v] of Object.entries(map)){ if(seen[k]) fs.appendFileSync("download.txt", seen[k]+" "+v+"\n"); else console.log("MISSING",k); }
' && while read url out; do curl -sS "$url" -o "$out"; done < download.txt && rm download.txt fonts.css && ls -la && file *.woff2 | head

cd assets/fonts && curl -sS -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36" "https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=Inter:wght@400;500;600;700;800&display=swap" -o fonts.css && node -e '
const fs=require("fs");
const css=fs.readFileSync("fonts.css","utf8");
const blocks=css.split("@font-face").slice(1);
let out="";
for(const b of blocks){
  const fam=(b.match(/font-family:\s*.([^;\x27"]+)/)||[])[1];
  const wt=(b.match(/font-weight:\s*(\d+)/)||[])[1];
  const url=(b.match(/url\((https:[^)]+)\)/)||[])[1];
  if(!fam||!wt||!url) continue;
  if(!b.includes("U+0000-00FF")) continue;
  out += fam.trim().toLowerCase()+"-"+wt+" "+url+"\n";
}
fs.writeFileSync("download.txt",out);
console.log(out);
'

