(()=>{'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d');
const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)];
let W=0,H=0,dpr=1,now=0,last=0,elapsed=0,paused=false,screen='play',level=18,xp=64,hp=248,maxHp=248,mp=86,maxMp=86,potions=3,gold=348,shards=4,mastery=72,kills=5,questGoal=12,wave=3,skillCD=0,dodgeCD=0,attackCD=0,invuln=0,toastTimer=0,selectedItem=-1,modifiers={elite:false,fragile:false,abyss:false};
const player={x:0,y:0,r:13,face:0,speed:155};const enemies=[],drops=[],effects=[],particles=[],keys={};let joy={x:0,y:0,active:false,id:null},pointer={};
const items=[{name:'Paslı Uzun Kılıç',icon:'⚔',rarity:'Sıradan',power:24,type:'weapon'},{name:'Kül Örme Pelerini',icon:'◈',rarity:'Büyülü',power:18,type:'armor'},{name:'Kurt Dişi Tılsım',icon:'✧',rarity:'Nadir',power:31,type:'charm'}];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function spawnEnemy(x,y,boss=false){let elite=modifiers.elite&&Math.random()<.13;enemies.push({x,y,r:boss?23:elite?16:12,hp:boss?290:elite?90:48,max:boss?290:elite?90:48,speed:boss?41:elite?48:rand(34,54),type:boss?'cinder':elite?'wraith':'wolf',elite,boss,hit:0,atk:rand(.8,2.4),phase:rand(0,7)})}
function spawnWave(){let count=Math.min(5+wave*2,24);for(let i=0;i<count;i++){let a=rand(0,Math.PI*2),r=rand(Math.min(W,H)*.34,Math.min(W,H)*.62);spawnEnemy(player.x+Math.cos(a)*r,player.y+Math.sin(a)*r)}if(wave%4===0)spawnEnemy(player.x+rand(-350,350),player.y+rand(-350,350),true);}
spawnWave();
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function addLoot(text,type='gold'){const el=document.createElement('div');el.className='loot-note '+type;el.textContent=text;$('#lootFeed').prepend(el);setTimeout(()=>el.remove(),4100)}
function closest(range=Infinity){let best=null,d=range;for(const e of enemies){let q=Math.hypot(e.x-player.x,e.y-player.y);if(q<d){d=q;best=e}}return best}
function hitEnemy(e,dmg){if(!e)return;e.hp-=dmg;e.hit=.16;effects.push({x:e.x,y:e.y,t:.22,max:.22,color:'#ffdb9a',r:15});for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:rand(-80,80),vy:rand(-80,80),t:.35,max:.35,color:'#dc8557'});if(e.hp<=0){let idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);kills++;xp+=rand(6,11);gold+=e.boss?70:e.elite?20:rand(2,7)|0;mastery=clamp(mastery+rand(.35,.8),0,100);if(kills%3===0){shards++;addLoot('+1 Kül Kristali','rare')}if(Math.random()<.19||e.boss){let rarity=Math.random()<.07?'Efsanevi':Math.random()<.27?'Nadir':'Büyülü';drops.push({x:e.x,y:e.y,item:{...pick(items),rarity},t:0});addLoot('✦ '+rarity+' eşya düştü',rarity==='Efsanevi'||rarity==='Nadir'?'rare':'gold')}if(kills<=questGoal&&kills%2===0){$('#questSummary').textContent=`${Math.min(kills,questGoal)} / ${questGoal} Kül Kurdu`;if(kills>=questGoal)toast('Görev tamamlandı! Ödülünü almak için dokun.')}if(xp>=100){xp-=100;level++;maxHp+=8;hp=Math.min(maxHp,hp+30);$('#levelFlash b').textContent=level;$('#levelFlash').classList.remove('show');void $('#levelFlash').offsetWidth;$('#levelFlash').classList.add('show')}if(enemies.length===0){wave++;setTimeout(()=>{if(!paused&&screen==='play'){spawnWave();$('#waveNum').textContent=String(wave).padStart(2,'0');toast('Yeni düşman dalgası yaklaşıyor…')}},1200)}}}
function attack(){if(paused||screen!=='play'||attackCD>0)return;attackCD=.32;let e=closest(100);let ang=e?Math.atan2(e.y-player.y,e.x-player.x):player.face;player.face=ang;effects.push({x:player.x+Math.cos(ang)*26,y:player.y+Math.sin(ang)*26,t:.18,max:.18,color:'#e8c273',r:28,slash:true,angle:ang});if(e&&Math.abs(Math.atan2(Math.sin(Math.atan2(e.y-player.y,e.x-player.x)-ang),Math.cos(Math.atan2(e.y-player.y,e.x-player.x)-ang)))<1.6)hitEnemy(e,25+mastery*.12)}
function castSkill(){if(paused||screen!=='play'||skillCD>0)return;if(mp<22){toast('Yeterli manan yok.');return}mp-=22;skillCD=5.5;$('#chargeText').textContent='YENİLENİYOR';const t=performance.now();effects.push({x:player.x,y:player.y,t:.55,max:.55,color:'#a997e6',r:160,ring:true});for(const e of [...enemies])if(Math.hypot(e.x-player.x,e.y-player.y)<160)hitEnemy(e,49+mastery*.2);setTimeout(()=>{if(skillCD<=0)$('#chargeText').textContent='HAZIR'},5700)}
function dodge(){if(paused||screen!=='play'||dodgeCD>0)return;dodgeCD=2.2;invuln=.48;let dx=joy.x,dy=joy.y;if(Math.hypot(dx,dy)<.1){dx=Math.cos(player.face);dy=Math.sin(player.face)}player.x+=dx*85;player.y+=dy*85;effects.push({x:player.x,y:player.y,t:.35,max:.35,color:'#9ecbaa',r:34,ring:true})}
function drink(){if(potions<1){toast('İksir kalmadı.');return}if(hp>=maxHp){toast('Sağlığın zaten dolu.');return}potions--;hp=Math.min(maxHp,hp+88);$('#potionCount').textContent=potions;addLoot('✦ Sağlık iksiri kullanıldı','mat');}
const walkables=()=>{};

