function draw(){const sx=W/2-player.x,sy=H/2-player.y;ctx.clearRect(0,0,W,H);ctx.fillStyle='#19241b';ctx.fillRect(0,0,W,H);
// Seamless hand-painted forest floor, seeded details
const size=54,ox=((sx%size)+size)%size,oy=((sy%size)+size)%size;for(let y=-size;y<H+size;y+=size)for(let x=-size;x<W+size;x+=size){let wx=x-ox,wy=y-oy;let seed=Math.sin((Math.floor((x-ox)/size)*127.1+Math.floor((y-oy)/size)*311.7))*43758.5;let n=seed-Math.floor(seed);ctx.fillStyle=n>.83?'#202c20':n<.13?'#172119':'#1b271d';ctx.fillRect(x-ox,y-oy,size+1,size+1);if(n>.55){ctx.fillStyle='#80906a18';ctx.beginPath();ctx.ellipse(x-ox+17+n*24,y-oy+20+n*20,5,2,.4,0,Math.PI*2);ctx.fill()}if(n>.91){ctx.fillStyle='#d2c19a55';ctx.beginPath();ctx.arc(x-ox+34,y-oy+38,1.3,0,7);ctx.fill()}}
// Worn looping stone path
ctx.save();ctx.translate(sx,sy);ctx.strokeStyle='#71684b24';ctx.lineWidth=118;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-850,-440);ctx.bezierCurveTo(-380,-130,-280,290,170,140);ctx.bezierCurveTo(550,10,520,-320,930,-370);ctx.stroke();ctx.strokeStyle='#c0aa7920';ctx.lineWidth=2;ctx.setLineDash([5,12]);ctx.stroke();ctx.setLineDash([]);
// Decorative stones and fallen logs
for(let i=-12;i<=12;i++){let x=i*122+Math.sin(i*9)*30,y=Math.sin(i*3.2)*245+Math.cos(i*8)*80;ctx.fillStyle='#0c110d55';ctx.beginPath();ctx.ellipse(x+3,y+8,rand(12,21),rand(7,12),.3,0,7);ctx.fill();ctx.fillStyle='#626352';ctx.beginPath();ctx.ellipse(x,y,rand(9,17),rand(5,9),.3,0,7);ctx.fill();ctx.fillStyle='#9a9672';ctx.beginPath();ctx.ellipse(x-3,y-2,5,2,.3,0,7);ctx.fill()}
// Mossy forest crowns (fixed world coordinates)
for(let i=0;i<60;i++){let x=Math.sin(i*86.31)*760,y=Math.cos(i*127.91)*550;if(Math.hypot(x,y)<95)continue;let r=rand(22,39);ctx.fillStyle='#080d0a6b';ctx.beginPath();ctx.ellipse(x+6,y+11,r*1.04,r*.77,.3,0,7);ctx.fill();ctx.fillStyle=['#243629','#29382a','#31402d','#27372c'][i%4];ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.fillStyle='#738054';ctx.globalAlpha=.16;ctx.beginPath();ctx.arc(x-r*.2,y-r*.22,r*.65,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#82905c55';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,r-2,.2,2.4);ctx.stroke();ctx.fillStyle='#d6d09b';ctx.globalAlpha=.52;ctx.beginPath();ctx.arc(x-r*.4,y-r*.34,2,0,7);ctx.fill();ctx.globalAlpha=1}
ctx.restore();
// Ground loot glows
for(const d of drops){d.t+=.016;let x=d.x+sx,y=d.y+sy;ctx.save();ctx.translate(x,y);ctx.rotate(d.t*1.1);ctx.shadowBlur=18;ctx.shadowColor=d.item.rarity==='Efsanevi'?'#ffbf43':'#c899e8';ctx.fillStyle=d.item.rarity==='Efsanevi'?'#f0c767':'#d0a9ea';ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(7,0);ctx.lineTo(0,8);ctx.lineTo(-7,0);ctx.fill();ctx.restore();ctx.fillStyle='#ede0c1';ctx.font='8px Inter';ctx.textAlign='center';ctx.fillText('AL',x,y+20)}
// Enemies with readable shadows and directional faces
for(const e of enemies){let x=e.x+sx,y=e.y+sy;if(x<-70||x>W+70||y<-70||y>H+70)continue;ctx.fillStyle='#080b09a0';ctx.beginPath();ctx.ellipse(x,y+8,e.r*1.15,e.r*.64,0,0,7);ctx.fill();let col=e.boss?'#774a38':e.elite?'#76547a':'#6d5640';ctx.fillStyle=e.hit>0?'#f2c99a':col;ctx.beginPath();ctx.arc(x,y,e.r,0,7);ctx.fill();ctx.fillStyle=e.boss?'#a16a48':e.elite?'#a478a8':'#8c7450';ctx.beginPath();ctx.ellipse(x-3,y-4,e.r*.72,e.r*.47,-.25,0,7);ctx.fill();ctx.fillStyle=e.elite?'#e698e5':'#e6b778';ctx.beginPath();ctx.arc(x+4,y-2,2,0,7);ctx.arc(x+9,y-2,2,0,7);ctx.fill();if(e.elite||e.boss){ctx.fillStyle='#0b100de0';ctx.fillRect(x-e.r,y-e.r-8,e.r*2,3);ctx.fillStyle=e.boss?'#da7559':'#bd80ce';ctx.fillRect(x-e.r,y-e.r-8,e.r*2*e.hp/e.max,3)}e.hit=Math.max(0,e.hit-.016}
// Player shadow, cloak, hood and blade
const px=W/2,py=H/2;ctx.fillStyle='#0609069c';ctx.beginPath();ctx.ellipse(px,py+10,17,9,0,0,7);ctx.fill();ctx.fillStyle=invuln>0?'#bcebd2':'#64775c';ctx.beginPath();ctx.moveTo(px,py-10);ctx.quadraticCurveTo(px-17,py+1,px-10,py+13);ctx.lineTo(px+9,py+12);ctx.quadraticCurveTo(px+18,py+1,px+9,py-10);ctx.fill();ctx.fillStyle='#c4a36a';ctx.beginPath();ctx.arc(px,py-9,7,0,7);ctx.fill();ctx.fillStyle='#3f3227';ctx.beginPath();ctx.arc(px,py-11,7,Math.PI,0);ctx.fill();ctx.save();ctx.translate(px,py);ctx.rotate(player.face);ctx.strokeStyle='#d4c7a4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,-5);ctx.lineTo(21,-10);ctx.stroke();ctx.strokeStyle='#ab8356';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(7,-5);ctx.lineTo(10,-2);ctx.stroke();ctx.restore();
// Combat rings and hits
for(const a of effects){let progress=1-a.t/a.max;ctx.save();ctx.globalAlpha=clamp(a.t/a.max,0,1)*.8;ctx.strokeStyle=a.color;ctx.lineWidth=a.ring?2:3;ctx.shadowBlur=10;ctx.shadowColor=a.color;if(a.ring){ctx.beginPath();ctx.arc(a.x+sx,a.y+sy,a.r*(.45+progress*.55),0,7);ctx.stroke()}else if(a.slash){ctx.beginPath();ctx.arc(a.x+sx,a.y+sy,a.r, a.angle-.9,a.angle+.9);ctx.stroke()}else{ctx.beginPath();ctx.arc(a.x+sx,a.y+sy,4+progress*8,0,7);ctx.stroke()}ctx.restore();a.t-=.016}for(let i=effects.length-1;i>=0;i--)if(effects[i].t<=0)effects.splice(i,1);
