function draw(){function frame(){draw();if(!paused&&screen==='play')update();requestAnimationFrame(frame)}requestAnimationFrame(frame);
function update(){const t=performance.now()/1000,dt=Math.min(.04,last? t-last:.016);last=t;elapsed+=dt;skillCD=Math.max(0,skillCD-dt);dodgeCD=Math.max(0,dodgeCD-dt);attackCD=Math.max(0,attackCD-dt);invuln=Math.max(0,invuln-dt);if(skillCD<=0)$('#chargeText').textContent='HAZIR';$('#skillCooldown').style.display=skillCD>0?'block':'none';$('#skillCooldown').style.background=`conic-gradient(#080909a0 ${skillCD/5.5*360}deg,transparent 0deg)`;
let dx=joy.x,dy=joy.y;if(keys.ArrowLeft||keys.a)dx-=1;if(keys.ArrowRight||keys.d)dx+=1;if(keys.ArrowUp||keys.w)dy-=1;if(keys.ArrowDown||keys.s)dy+=1;let mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}if(mag>.08){player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt;player.face=Math.atan2(dy,dx)}
for(const e of enemies){let vx=player.x-e.x,vy=player.y-e.y,d=Math.hypot(vx,vy)||1;if(d>e.r+player.r+1){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt}e.atk-=dt;if(d<e.r+player.r+5&&e.atk<=0){e.atk=1.15;if(invuln<=0){hp-=e.boss?20:e.elite?13:8;invuln=.22;$('#screenFlash').classList.remove('hit');void $('#screenFlash').offsetWidth;$('#screenFlash').classList.add('hit');if(hp<=0){hp=maxHp*.42;player.x-=dx*35;player.y-=dy*35;gold=Math.max(0,gold-25);toast('Yere serildin. 25 altın kaybettin.')} }}}
for(let i=drops.length-1;i>=0;i--){const d=drops[i];if(Math.hypot(d.x-player.x,d.y-player.y)<34){let itm=d.item;items.push(itm);addLoot('✦ '+itm.name+' • '+itm.rarity,itm.rarity==='Efsanevi'||itm.rarity==='Nadir'?'rare':'gold');drops.splice(i,1)}}mp=Math.min(maxMp,mp+2.6*dt);syncHUD();}
function syncHUD(){const pct=(v,m)=>`${clamp(v/m*100,0,100)}%`;$('#hpFill').style.width=pct(hp,maxHp);$('#hpText').textContent=`${Math.ceil(hp)} / ${maxHp}`;$('#mpFill').style.width=pct(mp,maxMp);$('#mpText').textContent=`${Math.floor(mp)} / ${maxMp}`;$('#xpFill').style.width=`${xp}%`;$('#xpText').textContent=`%${Math.floor(xp)}`;$('#orbHp').style.height=pct(hp,maxHp);$('#orbMp').style.height=pct(mp,maxMp);$('#masteryFill').style.width=`${mastery}%`;$('#masteryText').textContent=`%${Math.floor(mastery)}`;$('#enemyCount').textContent=String(enemies.length).padStart(2,'0');let sec=Math.floor(elapsed);$('#clock').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function openPanel(type){paused=true;screen=type;const host=$('#panelContent');const title={bag:'Sırt Çantası',skills:'Ustalık ve Yetenekler',craft:'Ocak ve Üretim',map:'Kül Ormanı',quest:'Av Panosu'}[type]||'Mola';let body='';if(type==='bag'){body=`<div class="eyebrow">YOLCULUK DONANIMI</div><h2>${title}</h2><p class="subtitle">Eşyalarını karşılaştır, en iyi ganimeti kuşan. <b>${gold} altın</b> · <b>${shards} kül kristali</b></p><div class="panel-grid">${items.map((it,i)=>`<article class="item-card ${selectedItem===i?'selected':''}" data-item="${i}"><div class="item-title"><span class="item-icon">${it.icon}</span><span>${it.name}</span></div><div class="item-rarity">${it.rarity} · ${it.type==='weapon'?'Silah':it.type==='armor'?'Zırh':'Tılsım'}</div><div class="item-stats">+${it.power} ${it.type==='weapon'?'Saldırı':'Savunma'} ${it.power>(items[0]?.power||0)?'↑':''}</div></article>`).join('')}</div><div class="panel-row"><span id="compareText">Bir eşya seçerek ayrıntıları gör.</span><button class="panel-action" id="equipBtn">KUŞAN</button></div>`}
else if(type==='skills'){body=`<div class="eyebrow">KULLANDIKÇA GÜÇLEN</div><h2>${title}</h2><p class="subtitle">Silah ustalığı: <b>%${Math.floor(mastery)}</b> · Kılıç kullanımıyla artar. Ustalık puanı: <b>${Math.floor(level/2)}</b></p><div class="tree-layout"><article class="tree-card" data-skill="Yankı Darbesi"><div class="tree-icon">⚔</div><b>Yankı Darbesi</b><p>Ağır saldırı %18 daha fazla hasar verir.</p><small>✦ Pasif · Açık</small></article><article class="tree-card" data-skill="Ay Işığı"><div class="tree-icon">✧</div><b>Ay Işığı</b><p>Çevrendeki düşmanlara 49+ hasar. 22 mana.</p><small>✦ Aktif · 5,5 sn</small></article><article class="tree-card" data-skill="Kül Zırhı"><div class="tree-icon">◈</div><b>Kül Zırhı</b><p>Alınan hasarı %8 azaltır.</p><small>1 puan · ${level>=20?'Öğren':'Seviye 20'}</small></article><article class="tree-card" data-skill="Kanlı Hasat"><div class="tree-icon">☽</div><b>Kanlı Hasat</b><p>Her kritik vuruşta canını yenile.</p><small>2 puan · ${level>=24?'Öğren':'Seviye 24'}</small></article></div><div class="panel-row"><span>Ustalık, kullandığın her silahla ayrı yükselir.</span><button class="panel-action" id="masteryAction">USTALIĞI GELİŞTİR</button></div>`}
else if(type==='craft'){body=`<div class="eyebrow">TOPLA · DÖV · GÜÇLEN</div><h2>${title}</h2><p class="subtitle">Zindan ganimetlerini kalıcı güce dönüştür. Malzeme: <b>${shards} Kül Kristali</b></p><div class="recipe-card"><div><b>Ay Dövmesi Kılıcı</b><small>18 saldırı · Kül Kristali ×3 · Altın ×120</small></div><button class="panel-action" data-craft="sword" ${shards<3||gold<120?'disabled':''}>ÜRET</button></div><div class="recipe-card"><div><b>Kurt Postu Zırhı</b><small>24 savunma · Kül Kristali ×2 · Altın ×90</small></div><button class="panel-action" data-craft="armor" ${shards<2||gold<90?'disabled':''}>ÜRET</button></div><div class="recipe-card"><div><b>Sağlık İksiri ×2</b><small>Ot ×4 · Altın ×35 · Şu an: ${potions}</small></div><button class="panel-action" data-craft="potion" ${gold<35?'disabled':''}>ÜRET</button></div><div class="panel-row"><span>Üretim anında çantana eklenir.</span><span>✦ ${gold} Altın</span></div>`}
else if(type==='map'){body=`<div class="eyebrow">İSTEĞE BAĞLI TEHLİKE</div><h2>${title}</h2><p class="subtitle">Derin katlarda riskini kendin belirle. Her değiştirici ganimet ödülünü yükseltir.</p><div class="risk-card"><div><b>Seçkin Sürüsü</b><small>Seçkin yaratıklar +%13 · Ganimat +%30</small></div><button class="toggle ${modifiers.elite?'on':''}" data-mod="elite"></button></div><div class="risk-card"><div><b>Kırılgan Ruh</b><small>Düşünce 25 altın düşür · Ganimet +%45</small></div><button class="toggle ${modifiers.fragile?'on':''}" data-mod="fragile"></button></div><div class="risk-card"><div><b>Uçurum Yemini</b><small>Çıkış yok · Ölümde kül kristali kaybı · Ganimet +%80</small></div><button class="toggle ${modifiers.abyss?'on':''}" data-mod="abyss"></button></div><div class="panel-row"><span>Aktif değiştiriciler: ${Object.values(modifiers).filter(Boolean).length}</span><button class="panel-action" id="deeperBtn">DERİNE İN ↓</button></div>`}
else if(type==='quest'){body=`<div class="eyebrow">HAFİF İŞ · BÜYÜK ÖDÜL</div><h2>${title}</h2><p class="subtitle">Kamp sakinlerinin küçük işleri. Kısa oturumda bile ilerleme kaydet.</p><article class="quest-card"><div class="quest-badge">◇</div><div><h3>Kül Kurdu Avı</h3><p>${Math.min(kills,questGoal)} / ${questGoal} yaratık · Ödül: 180 XP, 90 altın</p><div class="quest-progress"><i style="width:${Math.min(kills/questGoal*100,100)}%"></i></div></div></article><article class="quest-card"><div class="quest-badge">♧</div><div><h3>Kristal Toplayıcısı</h3><p>${shards} / 6 Kül Kristali · Ödül: Nadir tılsım</p><div class="quest-progress"><i style="width:${Math.min(shards/6*100,100)}%"></i></div></div></article><div class="panel-row"><span>Görevler ilerlemeni hızlandırır, ana hikâye dayatmaz.</span><button class="panel-action" id="claimQuest" ${kills<questGoal?'disabled':''}>ÖDÜLÜ AL</button></div>`}
else{body=`<div class="eyebrow">KÜL VE YANKI</div><h2>Yola kısa bir ara ver.</h2><p class="subtitle">Zindandan çıkmak için duraklatmayı kullanabilirsin.</p>`}host.innerHTML=body;$('#scrim').classList.add('open');}

