function syncHUD(){const pct=(v,m)=>`${clamp(v/m*100,0,100)}%`;$('#hpFill').style.width=pct(hp,maxHp);$('#hpText').textContent=`${Math.ceil(hp)} / ${maxHp}`;$('#mpFill').style.width=pct(mp,maxMp);$('#mpText').textContent=`${Math.floor(mp)} / ${maxMp}`;$('#xpFill').style.width=`${xp}%`;$('#xpText').textContent=`%${Math.floor(xp)}`;$('#orbHp').style.height=pct(hp,maxHp);$('#orbMp').style.height=pct(mp,maxMp);$('#masteryFill').style.width=`${mastery}%`;$('#masteryText').textContent=`%${Math.floor(mastery)}`;$('#enemyCount').textContent=String(enemies.length).padStart(2,'0');$('#potionCount').textContent=potions;$('#waveNum').textContent=String(wave).padStart(2,'0');let sec=Math.floor(elapsed);$('#clock').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}

