function spawnEnemy(x,y,boss=false){const elite=!boss&&modifiers.elite&&Math.random()<.17;let hpv=boss?290:elite?90:48;enemies.push({x,y,r:boss?23:elite?16:12,hp:hpv,max:hpv,speed:boss?41:elite?48:rand(34,54),elite,boss,hit:0,atk:rand(.8,2.4)})}
function spawnWave(){let count=Math.min(5+wave*2,24);for(let i=0;i<count;i++){let a=rand(0,Math.PI*2),r=rand(Math.min(W,H)*.34,Math.min(W,H)*.62);spawnEnemy(player.x+Math.cos(a)*r,player.y+Math.sin(a)*r)}if(wave%4===0)spawnEnemy(player.x+rand(-350,350),player.y+rand(-350,350),true)}
function closest(range=Infinity){let best=null,d=range;for(const e of enemies){let q=Math.hypot(e.x-player.x,e.y-player.y);if(q<d){d=q;best=e}}return best}
function gainXP(amount){xp+=amount;while(xp>=100){xp-=100;level++;maxHp+=8;hp=Math.min(maxHp,hp+30);$('#levelFlash b').textContent=level;$('#levelFlash').classList.remove('show');void $('#levelFlash').offsetWidth;$('#levelFlash').classList.add('show')}}
function hitEnemy(e,dmg){if(!e)return;e.hp-=dmg;e.hit=.16;effects.push({x:e.x,y:e.y,t:.22,max:.22,color:'#ffdb9a',r:15});for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:rand(-80,80),vy:rand(-80,80),t:.35,max:.35,color:'#dc8557'});if(e.hp>0)return;const idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);kills++;gainXP(rand(6,11));gold+=e.boss?70:e.elite?20:Math.floor(rand(2,8));mastery=clamp(mastery+rand(.35,.8),0,100);if(kills%3===0){shards++;addLoot('+1 Kül Kristali','rare')}if(Math.random()<.2||e.boss){let rarity=Math.random()<.07?'Efsanevi':Math.random()<.27?'Nadir':'Büyülü';drops.push({x:e.x,y:e.y,item:{...pick(items),rarity},t:0});addLoot('✦ '+rarity+' eşya düştü',rarity==='Efsanevi'||rarity==='Nadir'?'rare':'gold')}if(kills<=questGoal&&kills%2===0){$('#questSummary').textContent=`${Math.min(kills,questGoal)} / ${questGoal} Kül Kurdu`;if(kills>=questGoal)toast('Görev tamamlandı! Av panosuna dokun.')}if(!enemies.length){wave++;setTimeout(()=>{if(!paused&&screen==='play'){spawnWave();syncHUD();toast('Yeni düşman dalgası yaklaşıyor…')}},1200)}}
function attack(){if(paused||screen!=='play'||attackCD>0)return;attackCD=.32;const e=closest(100),ang=e?Math.atan2(e.y-player.y,e.x-player.x):player.face;player.face=ang;effects.push({x:player.x+Math.cos(ang)*26,y:player.y+Math.sin(ang)*26,t:.18,max:.18,color:'#e8c273',r:28,slash:true,angle:ang});if(e)hitEnemy(e,25+mastery*.12)}
function castSkill(){if(paused||screen!=='play'||skillCD>0)return;if(mp<22){toast('Yeterli manan yok.');return}mp-=22;skillCD=5.5;effects.push({x:player.x,y:player.y,t:.55,max:.55,color:'#a997e6',r:160,ring:true});for(const e of [...enemies])if(Math.hypot(e.x-player.x,e.y-player.y)<160)hitEnemy(e,49+mastery*.2)}
function dodge(){if(paused||screen!=='play'||dodgeCD>0)return;dodgeCD=2.2;invuln=.48;let dx=joy.x,dy=joy.y;if(Math.hypot(dx,dy)<.1){dx=Math.cos(player.face);dy=Math.sin(player.face)}player.x+=dx*85;player.y+=dy*85;effects.push({x:player.x,y:player.y,t:.35,max:.35,color:'#9ecbaa',r:34,ring:true})}
function drink(){if(potions<1){toast('İksir kalmadı.');return}if(hp>=maxHp){toast('Sağlığın zaten dolu.');return}potions--;hp=Math.min(maxHp,hp+88);addLoot('✦ Sağlık iksiri kullanıldı','mat');syncHUD()}
spawnWave();syncHUD();

