function openPanel(type){paused=true;screen=type;const host=$('#panelContent'),title={bag:'Sırt Çantası',skills:'Ustalık ve Yetenekler',craft:'Ocak ve Üretim',map:'Kül Ormanı',quest:'Av Panosu'}[type]||'Mola';let body='';if(type==='bag'){body=`<div class="eyebrow">YOLCULUK DONANIMI</div><h2>${title}</h2><p class="subtitle">Ganimetini karşılaştır. <b>${gold} altın</b> · <b>${shards} kül kristali</b></p><div class="panel-grid">${items.map((it,i)=>`<article class="item-card ${selectedItem===i?'selected':''}" data-item="${i}"><div class="item-title"><span class="item-icon">${it.icon}</span><span>${it.name}</span></div><div class="item-rarity">${it.rarity} · ${it.type==='weapon'?'Silah':it.type==='armor'?'Zırh':'Tılsım'}</div><div class="item-stats">+${it.power} ${it.type==='weapon'?'Saldırı':'Savunma'} ${it.power>(items[0]?.power||0)?'↑':''}</div></article>`).join('')}</div><div class="panel-row"><span id="compareText">${selectedItem<0?'Bir eşya seçerek ayrıntıları gör.':`Seçili: ${items[selectedItem]?.name} · Güç ${items[selectedItem]?.power}`}</span><button class="panel-action" id="equipBtn" ${selectedItem<0?'disabled':''}>KUŞAN</button></div>`}
else if(type==='skills'){body=`<div class="eyebrow">KULLANDIKÇA GÜÇLEN</div><h2>${title}</h2><p class="subtitle">Kılıç ustalığı: <b>%${Math.floor(mastery)}</b> · Ustalık puanı: <b>${Math.floor(level/2)}</b></p><div class="tree-layout"><article class="tree-card"><div class="tree-icon">⚔</div><b>Yankı Darbesi</b><p>Saldırı kullanımıyla ustalık artar.</p><small>✦ Pasif · Açık</small></article><article class="tree-card"><div class="tree-icon">✧</div><b>Ay Işığı</b><p>Yakındaki düşmanlara alan hasarı. 22 mana.</p><small>✦ Aktif · 5,5 sn</small></article><article class="tree-card ${level<20?'locked':''}" data-skill="armor"><div class="tree-icon">◈</div><b>Kül Zırhı</b><p>Alınan hasarı %8 azaltır.</p><small>1 puan · ${level>=20?'Öğren':'Seviye 20'}</small></article><article class="tree-card ${level<24?'locked':''}" data-skill="harvest"><div class="tree-icon">☽</div><b>Kanlı Hasat</b><p>Her düşmanda canını bir miktar yenile.</p><small>2 puan · ${level>=24?'Öğren':'Seviye 24'}</small></article></div><div class="panel-row"><span>Ustalık, silahını kullandıkça yükselir.</span><button class="panel-action" id="masteryAction">USTALIĞI GELİŞTİR</button></div>`}
else if(type==='craft'){body=`<div class="eyebrow">TOPLA · DÖV · GÜÇLEN</div><h2>${title}</h2><p class="subtitle">Malzeme: <b>${shards} Kül Kristali</b> · <b>${gold} altın</b></p><div class="recipe-card"><div><b>Ay Dövmesi Kılıcı</b><small>+18 saldırı · Kristal ×3 · Altın ×120</small></div><button class="panel-action" data-craft="sword" ${shards<3||gold<120?'disabled':''}>ÜRET</button></div><div class="recipe-card"><div><b>Kurt Postu Zırhı</b><small>+24 savunma · Kristal ×2 · Altın ×90</small></div><button class="panel-action" data-craft="armor" ${shards<2||gold<90?'disabled':''}>ÜRET</button></div><div class="recipe-card"><div><b>Sağlık İksiri ×2</b><small>Ot ×4 · Altın ×35 · Şu an: ${potions}</small></div><button class="panel-action" data-craft="potion" ${gold<35?'disabled':''}>ÜRET</button></div><div class="panel-row"><span>Eşyalar doğrudan çantana eklenir.</span><span>✦ ${gold} Altın</span></div>`}
else if(type==='map'){body=`<div class="eyebrow">İSTEĞE BAĞLI TEHLİKE</div><h2>${title}</h2><p class="subtitle">Her değiştirici tehlikeyi artırır; ganimet de artar.</p><div class="risk-card"><div><b>Seçkin Sürüsü</b><small>Seçkin yaratıklar · Ganimat +%30</small></div><button class="toggle ${modifiers.elite?'on':''}" data-mod="elite"></button></div><div class="risk-card"><div><b>Kırılgan Ruh</b><small>Düşünce 25 altın kaybı · Ganimat +%45</small></div><button class="toggle ${modifiers.fragile?'on':''}" data-mod="fragile"></button></div><div class="risk-card"><div><b>Uçurum Yemini</b><small>Ölümde kül kristali kaybı · Ganimat +%80</small></div><button class="toggle ${modifiers.abyss?'on':''}" data-mod="abyss"></button></div><div class="panel-row"><span>Etkin değiştirici: ${Object.values(modifiers).filter(Boolean).length}</span><button class="panel-action" id="deeperBtn">DERİNE İN ↓</button></div>`}
else if(type==='quest'){body=`<div class="eyebrow">HAFİF İŞ · BÜYÜK ÖDÜL</div><h2>${title}</h2><p class="subtitle">Kamp sakinlerinin küçük işleri. Kısa oturumda bile ilerleme kaydet.</p><article class="quest-card"><div class="quest-badge">◇</div><div><h3>Kül Kurdu Avı</h3><p>${Math.min(kills,questGoal)} / ${questGoal} yaratık · Ödül: 180 XP, 90 altın</p><div class="quest-progress"><i style="width:${Math.min(kills/questGoal*100,100)}%"></i></div></div></article><article class="quest-card"><div class="quest-badge">♧</div><div><h3>Kristal Toplayıcısı</h3><p>${shards} / 6 Kül Kristali · Ödül: Nadir tılsım</p><div class="quest-progress"><i style="width:${Math.min(shards/6*100,100)}%"></i></div></div></article><div class="panel-row"><span>Görevler ilerlemeni hızlandırır.</span><button class="panel-action" id="claimQuest" ${kills<questGoal?'disabled':''}>ÖDÜLÜ AL</button></div>`}
else body=`<div class="eyebrow">KÜL VE YANKI</div><h2>Yola kısa bir ara ver.</h2><p class="subtitle">Oyun duraklatıldı.</p>`;host.innerHTML=body;$('#scrim').classList.add('open')}
function closePanel(){paused=false;screen='play';$('#scrim').classList.remove('open')}

