function bindPanel(){const host=$('#panelContent');host.onclick=e=>{const item=e.target.closest('[data-item]');if(item){selectedItem=Number(item.dataset.item);const it=items[selectedItem];$('#compareText').textContent=`Seçili: ${it.name} · Güç ${it.power}`;host.querySelectorAll('.item-card').forEach(n=>n.classList.toggle('selected',n===item));$('#equipBtn').disabled=false;return}const craft=e.target.closest('[data-craft]');if(craft){doCraft(craft.dataset.craft);return}const mod=e.target.closest('[data-mod]');if(mod){modifiers[mod.dataset.mod]=!modifiers[mod.dataset.mod];openPanel('map');return}if(e.target.closest('#deeperBtn')){closePanel();wave++;spawnWave();toast('Daha derin kat: düşmanlar güçleniyor.');return}if(e.target.closest('#equipBtn')){if(selectedItem<0)return;const it=items[selectedItem];equipped[it.type]=selectedItem;toast(`${it.name} kuşanıldı.`);openPanel('bag');return}if(e.target.closest('#masteryAction')){if(gold<100){toast('Geliştirmek için 100 altın gerek.');return}gold-=100;mastery=clamp(mastery+8,0,100);toast('Kılıç ustalığın arttı.');openPanel('skills');syncHUD();return}if(e.target.closest('#claimQuest')){if(kills<questGoal||claimedHunt)return;claimedHunt=true;gold+=90;gainXP(180);toast('Av ödülü alındı: 90 altın, 180 XP.');openPanel('quest');syncHUD();return}const skill=e.target.closest('[data-skill]');if(skill){const name=skill.dataset.skill;if(name==='armor'&&level>=20&&gold>=60){armorSkill=true;gold-=60;toast('Kül Zırhı öğrenildi.')}else if(name==='harvest'&&level>=24&&gold>=120){harvestSkill=true;gold-=120;toast('Kanlı Hasat öğrenildi.')}else toast(level<(name==='armor'?20:24)?'Gerekli seviyeye henüz ulaşmadın.':'Geliştirme için altın yetersiz.');openPanel('skills');syncHUD()}}}
