function draw(){const camX=player.x,camY=player.y;drawGround(camX,camY);for(const d of drops){const [x,y]=worldXY(d.x,d.y),bob=Math.sin(d.t*4)*4;ctx.save();ctx.shadowColor='#efc66c';ctx.shadowBlur=18;ctx.fillStyle='#f0cb75';ctx.beginPath();ctx.arc(x,y+bob,6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff0c4';ctx.font='12px serif';ctx.textAlign='center';ctx.fillText('✦',x,y+bob-10);ctx.restore()}
for(const e of enemies){const [x,y]=worldXY(e.x,e.y);ctx.save();ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(x,y+e.r*.7,e.r*1.1,e.r*.55,0,0,Math.PI*2);ctx.fill();ctx.translate(x,y);let flash=e.hit>0;ctx.fillStyle=flash?'#f4d8b2':e.boss?'#774237':e.elite?'#94704b':'#705347';ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.boss?'#d18b63':'#b49a74';ctx.beginPath();ctx.arc(-e.r*.28,-e.r*.2,e.r*.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e65d50';ctx.beginPath();ctx.arc(-4,-2,2,0,Math.PI*2);ctx.arc(4,-2,2,0,Math.PI*2);ctx.fill();if(e.elite||e.boss){ctx.strokeStyle=e.boss?'#e1a35f':'#e0c47e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+4,-Math.PI*.8,Math.PI*.8);ctx.stroke()}ctx.restore();if(e.hp<e.max){ctx.fillStyle='#201b18';ctx.fillRect(x-e.r,y-e.r-10,e.r*2,3);ctx.fillStyle='#d87558';ctx.fillRect(x-e.r,y-e.r-10,e.r*2*clamp(e.hp/e.max,0,1),3)}}
